if (root == nullptr) return;
if (item < root->data) avlDelete(root->left, item);
else if (item > root->data) avlDelete(root->right, item);
else {
    if (root->left == nullptr && root->right == nullptr) {
        delete root;
        root = nullptr;
    }
    else if (root->left == nullptr) {
        TreeNode<int>* temp = root;
        root = root->right;
        delete temp;
    }
    else if (root->right == nullptr) {
        TreeNode<int>* temp = root;
        root = root->left;
        delete temp;
    }
    else {
        TreeNode<int>* temp = bstFindMin(root->right);
        root->data = temp->data;
        avlDelete(root->right, temp->data);
    }
}
int balanceFactor = bstHeight(root->left) - bstHeight(root->right);
if (balanceFactor > 1) {
    if (bstHeight(root->left->left) >= bstHeight(root->left->right))
        avlRotateRight(root);
    else {
        avlRotateLeft(root->left);
        avlRotateRight(root);
    }
}
else if (balanceFactor < -1) {
    if (bstHeight(root->right->right) >= bstHeight(root->right->left))
        avlRotateLeft(root);
    else {
        avlRotateRight(root->right);
        avlRotateLeft(root);
    }
}

